<#
.SYNOPSIS
  Generates "Token2 Companion Keyroost" from a clean keyroost checkout (Windows).

.DESCRIPTION
  Keeps all Token2 branding OUT of the keyroost repository. It:
    1. clones keyroost (upstream or your fork) at a chosen ref,
    2. applies the Token2 OTP feature patch (functionality only - no branding),
    3. overlays branding: app name, window title, brand tile, accent palette
       (Token2 red), the window icon, and companion-style layout tweaks,
    4. leaves a ready-to-build, rebranded project directory.

  Requires: git, python (3.8+), and a Rust toolchain to build afterwards.

.EXAMPLE
  .\rebrand-token2-companion.ps1
  .\rebrand-token2-companion.ps1 -Repo https://github.com/<you>/keyroost.git -Ref main -Out token2-companion
#>
param(
  [string]$Repo  = "https://github.com/framefilter/keyroost.git",
  [string]$Ref   = "main",
  [string]$Patch = "NUL",
  [string]$Out   = ".\token2-companion-keyroost",
  [string]$DocsUrl = "https://www.token2.swiss/kr-docs",
  [string]$Name = "Token2 Companion Rust version - Keyroost"
)

$ErrorActionPreference = "Stop"
$SelfDir = Split-Path -Parent $MyInvocation.MyCommand.Path
if ([string]::IsNullOrEmpty($Patch)) { $Patch = "NUL" }

$AppName     = $Name
$Tagline     = "Manage Token2 and other FIDO2 / OATH / PIV / OpenPGP keys"
$AccentHex   = "D60326"   # Token2 brand red
$AccentBright= "F2053D"
$AccentDeep  = "AE0009"

# Embedded window icon (Token2 T2 mark, PNG as base64) so the script
# is self-contained even without the branding\ folder next to it.
$EmbeddedIconB64 = @"

"@

function Say($m) { Write-Host "> $m" -ForegroundColor Magenta }

# Run git so its normal stderr progress ("Cloning into ...") is NOT treated as a
# terminating error under $ErrorActionPreference="Stop". Only a non-zero exit
# code is a real failure. Returns the exit code; never throws on stderr text.
function Invoke-Git {
  $old = $ErrorActionPreference
  $ErrorActionPreference = "Continue"
  try { & git @args 2>&1 | ForEach-Object { Write-Host "  $_" -ForegroundColor DarkGray } }
  finally { $ErrorActionPreference = $old }
  return $LASTEXITCODE
}

# ---- 1. clone --------------------------------------------------------------
if (Test-Path $Out) { throw "output dir '$Out' already exists - remove it or pass -Out" }
Say "Cloning $Repo @ $Ref"
if ((Invoke-Git clone $Repo $Out) -ne 0) { throw "git clone failed" }
if ((Invoke-Git -C $Out checkout $Ref) -ne 0) { throw "git checkout failed" }
# Resolve to an absolute path: .NET file APIs below ignore PowerShell's
# current directory and would otherwise resolve relative paths against the
# process working dir (often the user home).
$Out = (Resolve-Path $Out).Path

# ---- 2. apply the OTP feature patch ----------------------------------------
# The Token2 OTP feature is merged upstream, so the default is to skip the patch
# (-Patch NUL). Pass -Patch <file> only when building against a base that lacks it.
if ($Patch -eq "NUL" -or [string]::IsNullOrEmpty($Patch)) {
  Say "Skipping patch - the OTP feature is expected to be in $Repo already"
} elseif (Test-Path $Patch) {
  Say "Applying Token2 OTP feature patch"
  $chk = Invoke-Git -C $Out apply --check $Patch
  if ($chk -eq 0) {
    if ((Invoke-Git -C $Out apply $Patch) -ne 0) { throw "git apply failed" }
  } else {
    throw "patch did not apply cleanly against $Ref"
  }
} else {
  throw "patch file not found: $Patch"
}

# ---- 3. branding overlay ---------------------------------------------------
Say "Applying Token2 Companion branding"
$assetDir = Join-Path $Out "crates\keyroost\assets\branding"
New-Item -ItemType Directory -Force -Path $assetDir | Out-Null
# Materialize the window icon from the embedded base64 asset.
$iconFile = Join-Path $SelfDir "branding\icon-256.b64"
if (Test-Path $iconFile) { $b64 = (Get-Content $iconFile -Raw).Trim() } else { $b64 = $EmbeddedIconB64 }
[IO.File]::WriteAllBytes((Join-Path $assetDir "app-icon.png"), [Convert]::FromBase64String($b64))

python (Join-Path $SelfDir "apply_branding.py") `
  --root $Out `
  --app-name $AppName `
  --tagline $Tagline `
  --accent $AccentHex `
  --accent-bright $AccentBright `
  --accent-deep $AccentDeep `
  --docs-url $DocsUrl

Say "Done."
Write-Host ""
Write-Host "  Rebranded project:  $Out"
Write-Host "  Build & run:        cd $Out; cargo run -p keyroost"
Write-Host ""
Write-Host "  The keyroost repo itself was not modified with any branding."
